/**
 * Hand-rolled deterministic RNG: mulberry32. No `Math.random`, no crypto —
 * every generated byte is a pure function of (seed, corpus).
 */
export type Rng = () => number;

export function mulberry32(seed: number): Rng {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let mixed = Math.imul(state ^ (state >>> 15), 1 | state);
    mixed = (mixed + Math.imul(mixed ^ (mixed >>> 7), 61 | mixed)) ^ mixed;
    return ((mixed ^ (mixed >>> 14)) >>> 0) / 4294967296;
  };
}

/** Uniform integer in [min, max] inclusive; the range must be non-empty. */
export function intInRange(rng: Rng, min: number, max: number): number {
  const span = max - min + 1;
  if (span <= 0) {
    throw new Error(`empty integer range [${min}, ${max}]`);
  }
  return min + Math.floor(rng() * span);
}

/** Uniform pick from a non-empty list. */
export function pick<T>(rng: Rng, values: readonly T[]): T {
  const value = values[intInRange(rng, 0, values.length - 1)];
  if (value === undefined) {
    throw new Error("pick produced an undefined value");
  }
  return value;
}

export function chance(rng: Rng, probability: number): boolean {
  return rng() < probability;
}

/**
 * Weighted pick from `[value, weight]` entries. Weights are relative, not
 * normalized; zero weights are allowed (they can never be selected) but
 * negative weights and zero total weight are rejected.
 */
export function weightedPick<T>(rng: Rng, entries: readonly (readonly [T, number])[]): T {
  let total = 0;
  for (const [, weight] of entries) {
    if (weight < 0) {
      throw new Error("negative weight in weighted pick");
    }
    total += weight;
  }
  if (total === 0) {
    throw new Error("weighted pick needs a positive total weight");
  }
  let roll = rng() * total;
  for (const [value, weight] of entries) {
    roll -= weight;
    if (roll < 0) {
      return value;
    }
  }
  const last = entries[entries.length - 1];
  if (last === undefined) {
    throw new Error("weighted pick needs at least one entry");
  }
  return last[0];
}

/** Fisher–Yates shuffle of a copy; index order stays deterministic per seed. */
export function shuffle<T>(rng: Rng, values: readonly T[]): T[] {
  const out = [...values];
  for (let i = out.length - 1; i > 0; i--) {
    const j = intInRange(rng, 0, i);
    const a = out[i];
    const b = out[j];
    if (a === undefined || b === undefined) {
      throw new Error("shuffle hit an undefined entry");
    }
    out[i] = b;
    out[j] = a;
  }
  return out;
}

/** FNV-1a 32-bit hash — deterministic seed material for per-street ranges. */
export function hashString(input: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}
